-- C-04 customer receipts/advances. No historical document repairs.
set local lock_timeout='5s';set local statement_timeout='60s';
create schema customer_payment_private;
revoke all on schema customer_payment_private from public,anon,authenticated,service_role;
grant usage on schema customer_payment_private to authenticated;
create function customer_payment_private.access(a text) returns bigint language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select asset_posting_private.access('sales:customer-payments',a)$$;
create function customer_payment_private.context() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare v boolean;c boolean;e boolean;d boolean;begin
 perform asset_posting_private.identity();v:=asset_posting_private.allowed('sales:customer-payments','view');c:=asset_posting_private.allowed('sales:customer-payments','create');e:=asset_posting_private.allowed('sales:customer-payments','edit');d:=asset_posting_private.allowed('sales:customer-payments','delete');
 if not(v or c or e or d) then raise exception using errcode='42501',message='Sin acceso a cobros de clientes.';end if;return jsonb_build_object('canView',v,'canCreate',c,'canEdit',e,'canDelete',d);end$$;
do $$declare f record;body text;n text;names text[]:=array['customer_payment_advance_detail','customer_payment_options','customer_payment_detail','save_customer_payment_without_withholding','customer_payment_report','save_customer_payment_before_intercompany_receivable','save_customer_payment_with_advances_before_intercompany_receiva','customer_payment_edit_options','save_customer_payment','customer_available_advances','customer_payment_advance_summary','save_customer_payment_with_advances_without_withholding_total','save_customer_payment_with_advances_before_bank_fee','delete_customer_payment_before_bank_fee','save_customer_payment_with_advances','delete_customer_payment','customer_payment_bank_fee_summary','customer_payment_bank_fee_detail','customer_payment_realized_fx_account'];begin
 for f in select oid::regprocedure signature from pg_proc where pronamespace='public'::regnamespace and proname=any(names) loop execute format('alter function %s set schema customer_payment_private',f.signature);end loop;
 for f in select oid::regprocedure signature from pg_proc where pronamespace='customer_payment_private'::regnamespace and proname=any(names) loop
 execute format('alter function %s set search_path=pg_catalog,public,pg_temp',f.signature);body:=pg_get_functiondef(f.signature);
 foreach n in array names loop body:=replace(body,'public.'||n||'(','customer_payment_private.'||n||'(');body:=regexp_replace(body,'(?<![a-zA-Z0-9_.])'||n||'\(','customer_payment_private.'||n||'(','g');end loop;
 -- PostgreSQL stores this historical identifier truncated to 63 bytes.
 body:=replace(body,'public.save_customer_payment_with_advances_before_intercompany_receivable(','customer_payment_private.save_customer_payment_with_advances_before_intercompany_receiva(');
 body:=replace(body,'public.bank_fee_expense_account(','bank_fee_private.expense_account(');
 if f.signature::text like 'customer_payment_private.customer_available_advances(%' then body:=replace(body,$needle$and a.account_number='218001'$needle$,$replacement$and j.subsidiary_id=active_subsidiary_id() and not exists(select 1 from public.journal reversed where reversed.reversed_from_journal_id=j.journal_id) and a.account_number='218001'$replacement$);end if;
 if f.signature::text like 'customer_payment_private.customer_payment_advance_detail(%' then body:=replace(body,'where a.payment_id=p_payment_id','where j.subsidiary_id=active_subsidiary_id() and a.payment_id=p_payment_id');end if;
 execute body;end loop;
 body:=pg_get_functiondef('sales_invoice_private.rebuild_customer_payment_receivable_fx(bigint,numeric,bigint)'::regprocedure);
 if position('public.customer_payment_realized_fx_account(' in body)=0 then raise exception 'Unexpected FX helper';end if;
 execute replace(body,'public.customer_payment_realized_fx_account(','customer_payment_private.customer_payment_realized_fx_account(');
end$$;
create function customer_payment_private.visible(pid bigint) returns boolean language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin return asset_posting_private.allowed('sales:customer-payments','view') and exists(select 1 from public.customer_payment p join public."transaction" t using(transaction_id) join public.bank_account b using(bank_account_id) where p.payment_id=pid and t.subsidiary_id=asset_posting_private.identity() and b.subsidiary_id=t.subsidiary_id);end$$;
create function customer_payment_private.available(iid bigint,excluded bigint default null) returns numeric language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$
 select greatest(least(i.total_amount,
 case when exists(select 1 from public.sales_invoice_withholding where invoice_id=iid and recognized_at_invoice) then i.receivable_amount else coalesce(nullif(i.receivable_amount,0),i.total_amount) end,
 (case when exists(select 1 from public.sales_invoice_withholding where invoice_id=iid and recognized_at_invoice) then i.receivable_amount else coalesce(nullif(i.receivable_amount,0),i.total_amount) end)
 +coalesce((select sum(n.amount) from public.debit_note n join public.journal j on j.journal_id=n.journal_id join public."transaction" t on t.transaction_id=n.transaction_id where n.invoice_id=iid and j.subsidiary_id=i.subsidiary_id and t.subsidiary_id=i.subsidiary_id and j.status='CONTABILIZADO' and not exists(select 1 from public.journal where reversed_from_journal_id=j.journal_id) and not exists(select 1 from public.status where status_id=t.status_id and upper(code) in('ANULADO','CANCELADO'))),0)-coalesce((select sum(amount) from public.credit_note where invoice_id=iid),0))
 -coalesce((select sum(amount) from public.customer_payment_application where invoice_id=iid and payment_id is distinct from excluded),0),0) from public.invoice i where i.invoice_id=iid and i.subsidiary_id=asset_posting_private.identity()$$;
create function customer_payment_private.bank_window(bid bigint,d date) returns void language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin
 if exists(select 1 from public.bank_reconciliation where bank_account_id=bid and status='CERRADA' and reconciliation_date>=d)
 or exists(select 1 from public.quadratic_bank_reconciliations where bank_account_id=bid and status='CERRADA' and (period_year,period_month)>=(extract(year from d)::integer,extract(month from d)::integer)) then raise exception using errcode='55000',message='El movimiento pertenece a un período bancario conciliado.';end if;
end$$;
create function customer_payment_private.lock_source(pid bigint) returns public.customer_payment language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare p public.customer_payment;sid bigint:=asset_posting_private.identity();gross numeric;fee numeric;cash numeric;begin
 select cp.* into p from public.customer_payment cp join public."transaction" t using(transaction_id) where cp.payment_id=pid and t.subsidiary_id=sid;
 if not found then raise exception using errcode='42501',message='Cobro no disponible.';end if;
 perform 1 from public."transaction" where transaction_id=p.transaction_id for update;perform 1 from public.journal where journal_id=p.journal_id for update;select * into p from public.customer_payment where payment_id=pid for update;
 if exists(select 1 from public.customer_advance_application where payment_id=pid) or exists(select 1 from public.bank_deposit where customer_payment_id=pid) or exists(select 1 from public.journal where reversed_from_journal_id=p.journal_id) then raise exception using errcode='55000',message='El cobro tiene anticipos, depósitos o historia protegida.';end if;
 select coalesce(sum(amount),0) into gross from public.customer_payment_application where payment_id=pid;
 select coalesce(sum(amount),0) into fee from public.customer_payment_bank_fee where payment_id=pid;cash:=p.amount_received-fee;
 if p.status is distinct from 'APROBADO' or not asset_posting_private.finite(p.amount_received) or p.amount_received<=0 or gross<=0 or not asset_posting_private.finite(fee) or fee<0 or cash<0
 or abs(gross-coalesce((select sum(withholding_amount) from public.customer_payment_withholding where payment_id=pid),0)-p.amount_received)>.000001
 or not exists(select 1 from public.journal j join public."transaction" t on t.transaction_id=p.transaction_id join public.transaction_types tt using(transaction_type_id) join public.bank_account b on b.bank_account_id=p.bank_account_id where j.journal_id=p.journal_id and j.transaction_id=t.transaction_id and tt.abbreviation='COB_CLI' and j.journal_type='COBRO_CLIENTE' and j.status='CONTABILIZADO' and t.subsidiary_id=sid and j.subsidiary_id=sid and b.subsidiary_id=sid and b.currency_id=p.currency_id and t.currency_id=p.currency_id and j.currency_id=p.currency_id and j.journal_date=p.payment_date and t.tran_date=p.payment_date and j.fiscal_period_id=p.fiscal_period_id and t.fiscal_period_id=p.fiscal_period_id and j.exchange_rate=p.exchange_rate and t.exchange_rate=p.exchange_rate and t.total_amount=gross and j.journal_number=p.payment_number and t.tran_number=p.payment_number)
 then raise exception using errcode='55000',message='El origen contable del cobro requiere revisión.';end if;
 perform sales_invoice_private.period(p.fiscal_period_id,p.payment_date);perform customer_payment_private.bank_window(p.bank_account_id,p.payment_date);
 perform 1 from public.bank_transaction where transaction_id=p.transaction_id for update;
 if (select count(*) from public.bank_transaction where transaction_id=p.transaction_id)<>(case when cash>.000001 then 1 else 0 end)
 or exists(select 1 from public.bank_transaction bt where bt.transaction_id=p.transaction_id and(bt.bank_account_id is distinct from p.bank_account_id or bt.tran_type is distinct from 'COBRO_CLIENTE' or abs(bt.amount-cash)>.000001 or bt.tran_date is distinct from p.payment_date or bt.reconciliation_status is distinct from 'PENDIENTE_EN_TRANSITO' or coalesce(bt.is_opening_balance,false) or bt.opening_bank_item_id is not null or bt.opening_balance_line_id is not null))
 or exists(select 1 from public.bank_transaction bt join public.bank_reconciliation_match m using(bank_tran_id) where bt.transaction_id=p.transaction_id)
 or exists(select 1 from public.bank_transaction bt join public.quadratic_reconciliation_matches m using(bank_tran_id) where bt.transaction_id=p.transaction_id)
 or exists(select 1 from public.bank_transaction bt join public.quadratic_reconciliation_items m using(bank_tran_id) where bt.transaction_id=p.transaction_id)
 then raise exception using errcode='55000',message='El movimiento bancario está conciliado, vinculado o requiere revisión.';end if;return p;end$$;
create function customer_payment_private.prepare(p jsonb,pid bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare sid bigint:=customer_payment_private.access(case when pid is null then 'create' else 'edit' end);b public.bank_account;old public.customer_payment;i public.invoice;l public.journal_line;source_journal public.journal;item jsonb;key bigint;ids bigint[];amount numeric;gross numeric:=0;advance numeric:=0;rate numeric;fee numeric;w record;begin
 if jsonb_typeof(p) is distinct from 'object' or jsonb_typeof(p->'applications') is distinct from 'array' or jsonb_array_length(p->'applications') not between 1 and 1000 or(p?'advances' and(jsonb_typeof(p->'advances') is distinct from 'array' or jsonb_array_length(p->'advances')>1000)) then raise exception using errcode='22023',message='Seleccione entre 1 y 1000 facturas y hasta 1000 anticipos.';end if;
 if p ?| array['subsidiary_id','transaction_id','journal_id','payment_id','amount_received','status','created_by','currency_id','bank_fee_account_id'] then raise exception using errcode='42501',message='No puede sustituir el origen del cobro.';end if;
 if not exists(select 1 from public.customers c join public.entity_subsidiaries e using(customer_id) where c.customer_id=(p->>'customer_id')::bigint and e.subsidiary_id=sid and not coalesce((to_jsonb(c)->>'is_inactive')::boolean,false)) then raise exception using errcode='42501',message='Cliente no disponible.';end if;
 if pid is not null then select cp.* into old from public.customer_payment cp join public."transaction" t using(transaction_id) where payment_id=pid and t.subsidiary_id=sid;if not found then raise exception using errcode='42501',message='Cobro no disponible.';end if;end if;
 perform 1 from public.bank_account where bank_account_id in((p->>'account_id')::bigint,old.bank_account_id) and subsidiary_id=sid order by bank_account_id for update;
 select * into b from public.bank_account where bank_account_id=(p->>'account_id')::bigint and subsidiary_id=sid and not coalesce(is_credit_card,false);
 if not found or not exists(select 1 from public.subsidiary_currencies where subsidiary_id=sid and currency_id=b.currency_id) then raise exception using errcode='42501',message='Banco o moneda no disponible.';end if;
 perform asset_posting_private.account(b.account_id);if not exists(select 1 from public.chart_accounts where account_id=b.account_id and category='Activo') then raise exception using errcode='55000',message='La cuenta bancaria requiere cuenta de Activo.';end if;if not asset_posting_private.finite(b.balance) then raise exception using errcode='55000',message='Saldo bancario inválido.';end if;
 if not asset_posting_private.finite((p->>'rate')::numeric) or(p->>'rate')::numeric<=0 then raise exception using errcode='22023',message='Tipo de cambio inválido.';end if;
 rate:=sales_invoice_private.sales_invoice_official_exchange_rate(b.currency_id,(p->>'date')::date,sid);p:=p||jsonb_build_object('rate',rate);
 if nullif(trim(p->>'reference'),'') is null then raise exception using errcode='22023',message='Indique referencia bancaria.';end if;
 if nullif(p->>'location_id','') is not null and not inventory_balance_private.location((p->>'location_id')::bigint) then raise exception using errcode='42501',message='Ubicación no disponible.';end if;
 perform sales_invoice_private.period((p->>'period_id')::bigint,(p->>'date')::date);perform customer_payment_private.bank_window(b.bank_account_id,(p->>'date')::date);
 if (select count(*)<>count(distinct (x->>'invoice_id')::bigint) from jsonb_array_elements(p->'applications')x) or(select count(*)<>count(distinct (x->>'advanceLineId')::bigint) from jsonb_array_elements(coalesce(p->'advances','[]'))x) then raise exception using errcode='22023',message='No repita facturas ni anticipos.';end if;
 select array_agg(distinct id order by id) into ids from(select(x->>'invoice_id')::bigint id from jsonb_array_elements(p->'applications')x union select invoice_id from public.customer_payment_application where payment_id=pid)x;
 foreach key in array ids loop
 select * into i from public.invoice where invoice_id=key and subsidiary_id=sid;if not found then raise exception using errcode='42501',message='Factura no disponible.';end if;
 perform 1 from public."transaction" where transaction_id=i.transaction_id for update;perform 1 from public.journal where journal_id=i.journal_id for update;perform 1 from public.invoice where invoice_id=key for update;
 end loop;
 if pid is not null then old:=customer_payment_private.lock_source(pid);if old.customer_id is distinct from(p->>'customer_id')::bigint or old.currency_id is distinct from b.currency_id or old.location_id is distinct from nullif(p->>'location_id','')::bigint then raise exception using errcode='42501',message='El cobro conserva cliente, moneda y ubicación originales.';end if;end if;
 for item in select value from jsonb_array_elements(p->'applications') loop
 amount:=(item->>'amount')::numeric;if jsonb_typeof(item) is distinct from 'object' or not asset_posting_private.finite(amount) or amount<=0 then raise exception using errcode='22023',message='Aplicación inválida.';end if;
 select * into i from public.invoice where invoice_id=(item->>'invoice_id')::bigint and subsidiary_id=sid and customer_id=(p->>'customer_id')::bigint and currency_id=b.currency_id;
 if not found then raise exception using errcode='42501',message='La factura no corresponde al cliente y moneda.';end if;
 if not asset_posting_private.finite(i.total_amount) or not asset_posting_private.finite(coalesce(i.receivable_amount,i.total_amount)) or not asset_posting_private.finite(i.exchange_rate) or i.exchange_rate<=0
 or(not coalesce(i.is_opening_balance,false) and not exists(select 1 from public.journal ij join public."transaction" it on it.transaction_id=i.transaction_id join public.transaction_types tt using(transaction_type_id) where ij.journal_id=i.journal_id and ij.transaction_id=it.transaction_id and ij.subsidiary_id=sid and it.subsidiary_id=sid and tt.abbreviation='FAC_VEN' and ij.status='CONTABILIZADO' and ij.currency_id=i.currency_id and it.currency_id=i.currency_id)) or exists(select 1 from public.journal where reversed_from_journal_id=i.journal_id) then raise exception using errcode='55000',message='El origen de la factura requiere revisión.';end if;
 if amount>customer_payment_private.available(i.invoice_id,pid)+.000001 then raise exception using errcode='55000',message='El cobro supera el saldo pendiente, incluidas notas y retenciones.';end if;
 for w in select * from public.sales_invoice_withholding where invoice_id=i.invoice_id and application_moment='Al aplicar el pago' loop
 if not asset_posting_private.finite(w.withholding_amount) or w.withholding_amount<0 or not asset_posting_private.finite(w.rate_percentage) or w.rate_percentage not between 0 and 100 then raise exception using errcode='55000',message='Retención histórica inválida.';end if;perform asset_posting_private.account(w.asset_account_id);if not exists(select 1 from public.chart_accounts where account_id=w.asset_account_id and category='Activo') then raise exception using errcode='55000',message='Retención sin cuenta de Activo.';end if;end loop;
 perform asset_posting_private.account(coalesce(i.receivable_account_id,public.resolve_customer_receivable_account(sid,i.customer_id)));gross:=gross+amount;
 end loop;
 for key in select(x->>'advanceLineId')::bigint from jsonb_array_elements(coalesce(p->'advances','[]'))x order by 1 loop
 select jl.* into l from public.journal_line jl join public.journal j using(journal_id) join public."transaction" t using(transaction_id) where jl.journal_line_id=key and j.subsidiary_id=sid and t.subsidiary_id=sid and j.status='CONTABILIZADO' and t.currency_id=b.currency_id and j.currency_id=b.currency_id and jl.customer_id=(p->>'customer_id')::bigint;
 if not found then raise exception using errcode='42501',message='Anticipo no disponible.';end if;
 select * into source_journal from public.journal where journal_id=l.journal_id;perform 1 from public."transaction" where transaction_id=source_journal.transaction_id for update;perform 1 from public.journal where journal_id=source_journal.journal_id for update;select * into l from public.journal_line where journal_line_id=key for update;
 if not asset_posting_private.finite(l.debit) or not asset_posting_private.finite(l.credit) or l.credit-l.debit<=0 or exists(select 1 from public.journal where reversed_from_journal_id=source_journal.journal_id) or not exists(select 1 from public.chart_accounts where account_id=l.account_id and account_number='218001' and category='Pasivo') then raise exception using errcode='55000',message='Origen de anticipo inválido.';end if;
 perform asset_posting_private.account(l.account_id);select(x->>'amount')::numeric into amount from jsonb_array_elements(p->'advances')x where(x->>'advanceLineId')::bigint=key;
 if not asset_posting_private.finite(amount) or amount<=0 then raise exception using errcode='22023',message='Importe de anticipo inválido.';end if;
 if amount>l.credit-l.debit-coalesce((select sum(a.amount) from public.customer_advance_application a where a.source_journal_line_id=key),0)+.000001 then raise exception using errcode='55000',message='El anticipo supera el disponible.';end if;advance:=advance+amount;
 end loop;
 if advance>gross then raise exception using errcode='22023',message='Anticipos mayores que las aplicaciones.';end if;
 fee:=coalesce((p->>'bank_fee_amount')::numeric,0);if not asset_posting_private.finite(fee) or fee<0 or fee>gross-advance then raise exception using errcode='22023',message='Comisión bancaria inválida.';end if;
 if fee>0 then perform asset_posting_private.account(bank_fee_private.expense_account(sid));if not exists(select 1 from public.chart_accounts where account_id=bank_fee_private.expense_account(sid) and category='Gasto') then raise exception using errcode='22023',message='La comisión requiere una cuenta de Gasto.';end if;end if;
 return p;end$$;
create function customer_payment_private.check_result(r jsonb) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$
declare p public.customer_payment;d numeric;c numeric;cash numeric;begin
 select * into p from public.customer_payment where payment_id=(r->>'id')::bigint;cash:=(r->>'cashTotal')::numeric;
 select sum(debit),sum(credit) into d,c from public.journal_line where journal_id=p.journal_id;
 if p.payment_id is null or not asset_posting_private.finite(p.amount_received) or p.amount_received<=0 or not asset_posting_private.finite(cash) or cash<0 or not asset_posting_private.finite(d) or not asset_posting_private.finite(c) or d<=0 or abs(d-c)>.000001 then raise exception using errcode='55000',message='El cobro no genera asiento balanceado.';end if;
 select sum(debit_amount),sum(credit_amount) into d,c from public.gl_impact where transaction_id=p.transaction_id;
 if not asset_posting_private.finite(d) or not asset_posting_private.finite(c) or d<=0 or abs(d-c)>.000001 then raise exception using errcode='55000',message='El mayor del cobro no está balanceado.';end if;
 if (select count(*) from public.bank_transaction where transaction_id=p.transaction_id)<>(case when cash>.000001 then 1 else 0 end) or exists(select 1 from public.bank_transaction where transaction_id=p.transaction_id and(bank_account_id is distinct from p.bank_account_id or abs(amount-cash)>.000001)) then raise exception using errcode='55000',message='El ingreso no coincide con el movimiento bancario.';end if;
 return r;end$$;
create function customer_payment_private.protect_advance_source() returns trigger language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin
 if tg_table_name='journal_line' then
  if exists(select 1 from public.customer_advance_application where source_journal_line_id=old.journal_line_id) then raise exception using errcode='55000',message='El origen del anticipo aplicado conserva su historial.';end if;
 elsif tg_table_name='transaction' then
  if exists(select 1 from public.customer_advance_application a join public.journal_line l on l.journal_line_id=a.source_journal_line_id join public.journal j using(journal_id) where j.transaction_id=old.transaction_id) then raise exception using errcode='55000',message='La transacción del anticipo aplicado conserva su historial.';end if;
 else
  if (tg_op<>'INSERT' and exists(select 1 from public.customer_advance_application a join public.journal_line l on l.journal_line_id=a.source_journal_line_id where l.journal_id=old.journal_id))
  or (tg_op<>'DELETE' and exists(select 1 from public.customer_advance_application a join public.journal_line l on l.journal_line_id=a.source_journal_line_id where l.journal_id=new.reversed_from_journal_id)) then raise exception using errcode='55000',message='No se reescribe ni revierte un anticipo ya aplicado.';end if;
 end if;
 return case when tg_op='DELETE' then old else new end;
end$$;
create trigger customer_advance_source_line before update or delete on public.journal_line for each row execute function customer_payment_private.protect_advance_source();
create trigger customer_advance_source_header before insert or update or delete on public.journal for each row execute function customer_payment_private.protect_advance_source();
create trigger customer_advance_source_transaction before update or delete on public."transaction" for each row execute function customer_payment_private.protect_advance_source();
create function public.save_customer_payment_with_advances(p_payload jsonb,p_payment_id bigint default null) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare p jsonb;r jsonb;begin
 p:=customer_payment_private.prepare(p_payload,p_payment_id);r:=customer_payment_private.check_result(customer_payment_private.save_customer_payment_with_advances(p-'supports',p_payment_id));
 if p_payload?'supports' then perform sales_invoice_private.supports((r->>'journalId')::bigint,p_payload->'supports');end if;return r;end$$;
create function public.save_customer_payment(p_payload jsonb,p_payment_id bigint default null) returns jsonb language sql security definer set search_path=pg_catalog,public,pg_temp as $$select public.save_customer_payment_with_advances(p_payload,p_payment_id)$$;
create function public.delete_customer_payment(p_payment_id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$declare p public.customer_payment;i public.invoice;sid bigint:=customer_payment_private.access('delete');begin
 select cp.* into p from public.customer_payment cp join public."transaction" t using(transaction_id) where payment_id=p_payment_id and t.subsidiary_id=sid;if not found then raise exception using errcode='42501',message='Cobro no disponible.';end if;
 perform 1 from public.bank_account where bank_account_id=p.bank_account_id for update;
 for i in select inv.* from public.invoice inv join public.customer_payment_application a using(invoice_id) where a.payment_id=p_payment_id order by invoice_id loop perform 1 from public."transaction" where transaction_id=i.transaction_id for update;perform 1 from public.journal where journal_id=i.journal_id for update;perform 1 from public.invoice where invoice_id=i.invoice_id for update;end loop;
 p:=customer_payment_private.lock_source(p_payment_id);return customer_payment_private.delete_customer_payment(p_payment_id);end$$;
create function public.customer_payment_access() returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select customer_payment_private.context()$$;
create function customer_payment_private.detail(pid bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare jid bigint;begin
 select p.journal_id into jid from public.customer_payment p join public."transaction" t using(transaction_id) join public.bank_account b using(bank_account_id) where p.payment_id=pid and t.subsidiary_id=asset_posting_private.identity() and b.subsidiary_id=t.subsidiary_id;if not found then raise exception using errcode='42501',message='Cobro no disponible.';end if;
 return customer_payment_private.customer_payment_detail(pid)||jsonb_build_object('access',customer_payment_private.context(),'advances',customer_payment_private.customer_payment_advance_detail(pid),'bankFee',nullif(customer_payment_private.customer_payment_bank_fee_detail(pid),'{}'::jsonb),'supports',(select coalesce(jsonb_agg(jsonb_build_object('support_id',s.support_id,'support_type',s.support_type,'display_name',s.display_name,'file_name',s.file_name,'mime_type',s.mime_type,'file_size',s.file_size,'file_data',s.file_data,'support_url',s.support_url)),'[]') from public.journal_support s where journal_id=jid));end$$;
create function public.customer_payment_detail(p_payment_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform customer_payment_private.access('view');return customer_payment_private.detail(p_payment_id);end$$;
create function customer_payment_private.options(pid bigint default null) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare sid bigint:=asset_posting_private.identity();ctx jsonb:=customer_payment_private.context();r jsonb;fee bigint;begin
 r:=customer_payment_private.customer_payment_options();fee:=bank_fee_private.expense_account(sid);
 -- Receipt creation needs bank labels/currency, not disclosure of bank balances.
 r:=jsonb_set(r,'{accounts}',coalesce((select jsonb_agg(x-'balance') from jsonb_array_elements(r->'accounts')x join public.bank_account b on b.bank_account_id=(x->>'id')::bigint where b.subsidiary_id=sid and exists(select 1 from public.subsidiary_currencies where subsidiary_id=sid and currency_id=b.currency_id)),'[]'::jsonb));
 if not((ctx->>'canCreate')::boolean or(ctx->>'canEdit')::boolean) then return jsonb_build_object('access',ctx,'subsidiary',r->'subsidiary','customers','[]'::jsonb,'accounts','[]'::jsonb,'periods','[]'::jsonb,'rates','[]'::jsonb,'invoices','[]'::jsonb,'advances','[]'::jsonb,'bankFeeAccount',null);end if;
 return r||jsonb_build_object('access',ctx,'location',case when pid is null then r->'location' else(select jsonb_build_object('id',l.location_id,'name',l.name) from public.customer_payment p left join public.locations l using(location_id) where p.payment_id=pid) end,'bankFeeAccount',(select jsonb_build_object('id',account_id,'number',account_number,'name',account_name) from public.chart_accounts where account_id=fee),
 'advances',customer_payment_private.customer_available_advances(),
 'periods',(select coalesce(jsonb_agg(x),'[]') from jsonb_array_elements(r->'periods')x join public.fiscal_periods f on f.fiscal_period_id=(x->>'id')::bigint where not coalesce(f.gl_closed,false) and not coalesce(f.is_inactive,false)),
 'rates',(select coalesce(jsonb_agg(jsonb_build_object('fromCurrencyId',from_currency_id,'toCurrencyId',to_currency_id,'date',effective_date,'rate',spot_rate) order by effective_date desc),'[]') from public.exchange_rates e where(from_currency_id=(select currency_id from public.subsidiaries where subsidiary_id=sid) and exists(select 1 from public.subsidiary_currencies where subsidiary_id=sid and currency_id=e.to_currency_id)) or(to_currency_id=(select currency_id from public.subsidiaries where subsidiary_id=sid) and exists(select 1 from public.subsidiary_currencies where subsidiary_id=sid and currency_id=e.from_currency_id))),
 'invoices',(select coalesce(jsonb_agg(jsonb_build_object('id',i.invoice_id,'number',i.invoice_number,'customerId',i.customer_id,'date',i.invoice_date,'dueDate',i.due_date,'currencyId',i.currency_id,'currency',c.currency_code,'total',i.total_amount,'withholdingTotal',i.withholding_total,'receivable',i.receivable_amount,'currentApplied',coalesce((select sum(amount) from public.customer_payment_application where payment_id=pid and invoice_id=i.invoice_id),0),'balance',customer_payment_private.available(i.invoice_id),'editableBalance',customer_payment_private.available(i.invoice_id,pid)) order by i.invoice_date,i.invoice_id),'[]') from public.invoice i join public.currencies c using(currency_id) where i.subsidiary_id=sid and(customer_payment_private.available(i.invoice_id,pid)>.000001 or exists(select 1 from public.customer_payment_application where payment_id=pid and invoice_id=i.invoice_id))));end$$;
create function public.customer_payment_options() returns jsonb language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select customer_payment_private.options(null)$$;
create function public.customer_payment_edit_options(p_payment_id bigint) returns jsonb language plpgsql security definer set search_path=pg_catalog,public,pg_temp as $$begin
 perform customer_payment_private.access('edit');perform customer_payment_private.lock_source(p_payment_id);return customer_payment_private.options(p_payment_id)||jsonb_build_object('detail',customer_payment_private.detail(p_payment_id));end$$;
create function public.customer_payment_report(p_filters jsonb) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$declare r jsonb;s jsonb;f jsonb;begin
 perform customer_payment_private.access('view');r:=customer_payment_private.customer_payment_report(p_filters);s:=customer_payment_private.customer_payment_advance_summary();f:=customer_payment_private.customer_payment_bank_fee_summary();
 return r||jsonb_build_object('access',customer_payment_private.context(),'rows',(select coalesce(jsonb_agg(x||jsonb_build_object('bankFeeAccountNumber',(select a->>'expenseAccountNumber' from jsonb_array_elements(f)a where a->>'paymentId'=x->>'id'),'bankFeeAccountName',(select a->>'expenseAccountName' from jsonb_array_elements(f)a where a->>'paymentId'=x->>'id'),'grossTotal',(select sum(amount) from public.customer_payment_application where payment_id=(x->>'id')::bigint),'advanceTotal',coalesce((select(a->>'advanceTotal')::numeric from jsonb_array_elements(s)a where a->>'paymentId'=x->>'id'),0),'bankFeeTotal',coalesce((select(a->>'amount')::numeric from jsonb_array_elements(f)a where a->>'paymentId'=x->>'id'),0))),'[]') from jsonb_array_elements(r->'rows')x));end$$;
create function public.customer_available_advances() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform customer_payment_private.context();return customer_payment_private.customer_available_advances();end$$;
create function public.customer_payment_advance_summary() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform customer_payment_private.access('view');return customer_payment_private.customer_payment_advance_summary();end$$;
create function public.customer_payment_bank_fee_summary() returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform customer_payment_private.access('view');return customer_payment_private.customer_payment_bank_fee_summary();end$$;
create function public.customer_payment_advance_detail(p_payment_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform customer_payment_private.access('view');if not customer_payment_private.visible(p_payment_id) then raise exception using errcode='42501',message='Cobro no disponible.';end if;return customer_payment_private.customer_payment_advance_detail(p_payment_id);end$$;
create function public.customer_payment_bank_fee_detail(p_payment_id bigint) returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,pg_temp as $$begin perform customer_payment_private.access('view');if not customer_payment_private.visible(p_payment_id) then raise exception using errcode='42501',message='Cobro no disponible.';end if;return customer_payment_private.customer_payment_bank_fee_detail(p_payment_id);end$$;
create function customer_payment_private.support_allowed(jid bigint) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select not exists(select 1 from public.customer_payment where journal_id=jid)$$;
create function customer_payment_private.support_visible(jid bigint) returns boolean language sql stable security definer set search_path=pg_catalog,public,pg_temp as $$select not exists(select 1 from public.customer_payment where journal_id=jid) or exists(select 1 from public.customer_payment p where p.journal_id=jid and customer_payment_private.visible(p.payment_id))$$;
create policy customer_payment_support_read on public.journal_support as restrictive for select to authenticated using(customer_payment_private.support_visible(journal_id));
create policy customer_payment_support_insert on public.journal_support as restrictive for insert to authenticated with check(customer_payment_private.support_allowed(journal_id));
create policy customer_payment_support_update on public.journal_support as restrictive for update to authenticated using(customer_payment_private.support_allowed(journal_id)) with check(customer_payment_private.support_allowed(journal_id));
create policy customer_payment_support_delete on public.journal_support as restrictive for delete to authenticated using(customer_payment_private.support_allowed(journal_id));
do $$declare t text;p record;c record;begin foreach t in array array['customer_payment','customer_payment_application','customer_payment_withholding','customer_payment_bank_fee','customer_advance_application'] loop
 execute format('alter table public.%I enable row level security',t);for p in select policyname from pg_policies where schemaname='public' and tablename=t loop execute format('drop policy %I on public.%I',p.policyname,t);end loop;execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);
 for c in select column_name from information_schema.columns where table_schema='public' and table_name=t loop execute format('revoke all (%I) on public.%I from public,anon,authenticated,service_role',c.column_name,t);end loop;
 execute format('grant select on public.%I to authenticated',t);execute format('create policy customer_payment_read on public.%I for select to authenticated using(customer_payment_private.visible(payment_id))',t);end loop;end$$;
revoke all on all functions in schema customer_payment_private from public,anon,authenticated,service_role;
grant execute on function customer_payment_private.visible(bigint),customer_payment_private.support_allowed(bigint),customer_payment_private.support_visible(bigint) to authenticated;
revoke all on function public.protect_applied_customer_advance(),public.validate_customer_payment_application_receivable() from public,anon,authenticated,service_role;
revoke all on function public.customer_payment_access() from public,anon,authenticated,service_role;grant execute on function public.customer_payment_access() to authenticated;
revoke all on function public.customer_payment_advance_detail(bigint) from public,anon,authenticated,service_role;grant execute on function public.customer_payment_advance_detail(bigint) to authenticated;
revoke all on function public.customer_payment_options() from public,anon,authenticated,service_role;grant execute on function public.customer_payment_options() to authenticated;
revoke all on function public.customer_payment_detail(bigint) from public,anon,authenticated,service_role;grant execute on function public.customer_payment_detail(bigint) to authenticated;
revoke all on function public.customer_payment_report(jsonb) from public,anon,authenticated,service_role;grant execute on function public.customer_payment_report(jsonb) to authenticated;
revoke all on function public.customer_payment_edit_options(bigint) from public,anon,authenticated,service_role;grant execute on function public.customer_payment_edit_options(bigint) to authenticated;
revoke all on function public.save_customer_payment(jsonb,bigint) from public,anon,authenticated,service_role;grant execute on function public.save_customer_payment(jsonb,bigint) to authenticated;
revoke all on function public.customer_available_advances() from public,anon,authenticated,service_role;grant execute on function public.customer_available_advances() to authenticated;
revoke all on function public.customer_payment_advance_summary() from public,anon,authenticated,service_role;grant execute on function public.customer_payment_advance_summary() to authenticated;
revoke all on function public.save_customer_payment_with_advances(jsonb,bigint) from public,anon,authenticated,service_role;grant execute on function public.save_customer_payment_with_advances(jsonb,bigint) to authenticated;
revoke all on function public.delete_customer_payment(bigint) from public,anon,authenticated,service_role;grant execute on function public.delete_customer_payment(bigint) to authenticated;
revoke all on function public.customer_payment_bank_fee_summary() from public,anon,authenticated,service_role;grant execute on function public.customer_payment_bank_fee_summary() to authenticated;
revoke all on function public.customer_payment_bank_fee_detail(bigint) from public,anon,authenticated,service_role;grant execute on function public.customer_payment_bank_fee_detail(bigint) to authenticated;
notify pgrst,'reload schema';
